static const size_t OUI_PACKED_COUNT = sizeof(OUI_PACKED) / sizeof(OUI_PACKED[0]);

// The vendor for a 24-bit prefix (as mac_oui() returns it), or nullptr.
inline const char* oui_vendor(uint32_t oui) {
    size_t lo = 0, hi = OUI_PACKED_COUNT;
    while (lo < hi) {
        const size_t mid = lo + (hi - lo) / 2;
        const uint32_t p = OUI_PACKED[mid] >> 8;
        if (p == oui) return OUI_NAMES[OUI_PACKED[mid] & 0xFFu];
        if (p < oui) lo = mid + 1; else hi = mid;
    }
    return nullptr;
}
